fast_pseudocode:
# Lambda grid activates autotune — XBLOCK/YBLOCK injected from winning config
@triton.autotune(configs=[...], key=['ynumel', 'xnumel'])
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    ...

grid = lambda meta: (
    triton.cdiv(xnumel, meta['XBLOCK']),
    triton.cdiv(ynumel, meta['YBLOCK']),
)
kernel[grid](in_ptr, out_ptr, ynumel, xnumel)  # no explicit XBLOCK/YBLOCK kwargs
